package au.monster.tracker;
import java.util.*;
import java.time.*;
public final class FinanceTests {
    private static int passed;
    private static void eq(Object a,Object b){if(!Objects.equals(a,b))throw new AssertionError(a+" != "+b);}
    private static void test(String name,Runnable test){test.run();passed++;System.out.println("PASS "+name);}
    private static Finance.Result calculate(List<Ledger.Event> es){return Finance.calculate(es,Map.of(),Ledger.list(),Ledger.list(),Ledger.list(),Map.of());}
    private static Finance.Summary all(Finance.Result r){return Finance.summarize(r,Finance.period("all",LocalDate.now(Ledger.PERTH)));}
    public static void main(String[] args){long now=System.currentTimeMillis();
        test("opening FIFO loss and inventory value retain unknown dates",()->{var s=all(calculate(Ledger.opening(now)));eq(s.inventoryValue(),4167L);eq(s.losses(),833L);eq(s.purchases(),5000L);eq(s.unknownDateRows(),2L);eq(s.netProfit(),-833L);});
        test("single/deal FIFO costs and real fees",()->{var es=new ArrayList<>(Ledger.opening(now));es.add(Ledger.event("single",1,"cash",350,0,0,"",now,null));es.add(Ledger.event("deal",2,"card",600,25,0,"",now,null));var s=all(calculate(es));eq(s.revenue(),950L);eq(s.cogs(),624L);eq(s.cash(),350L);eq(s.card(),600L);eq(s.grossProfit(),326L);eq(s.netProfit(),-532L);eq(s.inventoryValue(),3543L);});
        test("later purchase does not reprice historical sale costs",()->{var es=new ArrayList<>(Ledger.opening(now));es.add(Ledger.event("single",1,"cash",350,0,0,"",now,null));long cost=calculate(es).rows().get(2).cogs();es.add(Ledger.event("restock",24,"none",0,0,9000,"",now,null));eq(calculate(es).rows().get(2).cogs(),cost);});
        test("sale undo reverses original cost and fee at correction date",()->{var es=new ArrayList<>(Ledger.opening(now));var sale=Ledger.event("deal",2,"card",600,25,0,"",now,null);es.add(sale);es.add(Ledger.event("undo",0,"none",0,0,0,"Mistake",now+1,sale.id()));var s=all(calculate(es));eq(s.cogs(),0L);eq(s.fees(),0L);eq(s.revenue(),0L);eq(s.inventoryValue(),4167L);});
        test("undo partially consumed restock records valuation correction",()->{var es=new ArrayList<>(Ledger.opening(now));var first=Ledger.event("restock",2,"none",0,0,1000,"",now,null);es.add(first);es.add(Ledger.event("missing",21,"none",0,0,0,"",now,null));es.add(Ledger.event("restock",2,"none",0,0,2000,"",now,null));es.add(Ledger.event("undo",0,"none",0,0,0,"Restock mistake",now,first.id()));var s=all(calculate(es));eq(s.inventoryValue(),1000L);eq(s.purchases(),7000L);eq(s.losses(),6000L);});
        test("FIFO flavour transfers preserve cost and profit attribution",()->{String product=Ledger.id();var es=new ArrayList<>(Ledger.opening(now));var sale=new Ledger.Event(Ledger.id(),now+2,now+2,"deal",2,"cash",600,0,0,"",null);es.add(sale);var transfer=new Catalog.Transfer(Ledger.id(),Catalog.LEGACY,product,10,now+1,"Identified",Ledger.OPEN_MISSING);var allocations=Map.of(sale.id(),Ledger.list(new Catalog.Allocation(product,2)));var result=Finance.calculate(es,allocations,Ledger.list(transfer),Ledger.list(),Ledger.list(),Map.of());eq(all(result).flavourProfit().get(product),184L);eq(all(result).inventoryValue(),3751L);});
        test("GST defaults unregistered and is frozen per transaction",()->{var es=new ArrayList<>(Ledger.opening(now));var sale=Ledger.event("single",1,"cash",350,0,0,"",now,null);es.add(sale);eq(all(calculate(es)).outputGst(),0L);var result=Finance.calculate(es,Map.of(),Ledger.list(),Ledger.list(),Ledger.list(),Map.of(sale.id(),new Finance.Tax(true,0,0,32)));eq(all(result).outputGst(),32L);eq(all(result).grossProfit(),110L);});
        test("expense GST and correction remain traceable",()->{var doc=new Purchases.Document(Ledger.id(),"expense","Supplier","",null,now,1100,100,"Travel","",null,Ledger.list());Map<String,Object> undo=new LinkedHashMap<>();undo.put("id",Ledger.id());undo.put("documentId",doc.id());undo.put("recordedAt",now);undo.put("note","Mistake");var r=Finance.calculate(Ledger.opening(now),Map.of(),Ledger.list(),Ledger.list(doc),Ledger.list(undo),Map.of(doc.id(),new Finance.Tax(true,100,100,0)));eq(all(r).expenses(),0L);eq(all(r).inputGst(),0L);eq(r.rows().size(),4);});
        test("dated reports exclude unknown history without fabricating dates",()->{var r=calculate(Ledger.opening(now));var s=Finance.summarize(r,Finance.period("day",LocalDate.now(Ledger.PERTH)));eq(s.rows().size(),0);eq(s.unknownDateRows(),2L);});
        test("Perth weekly quarterly and Australian financial year boundaries",()->{var d=LocalDate.of(2026,10,13);eq(Finance.period("week",d).label(),"2026-10-12 to 2026-10-18 (Perth)");eq(Finance.period("quarter",d).label(),"2026-10-01 to 2026-12-31 (Perth)");eq(Finance.period("financial_year",d).label(),"2026-07-01 to 2027-06-30 (Perth)");});
        test("report CSV includes correction references and escaping",()->{var es=new ArrayList<>(Ledger.opening(now));es.add(Ledger.event("single",1,"cash",350,0,0,"Receipt, \"review\"",now,null));String csv=Finance.csv(all(calculate(es)));eq(csv.contains("Receipt, \"\"review\"\""),true);});
        test("undo a mistaken received return preserves original sale cost",()->{var es=new ArrayList<>(Ledger.opening(now));var sale=Ledger.event("deal",2,"cash",600,0,0,"",now,null);es.add(sale);var returned=Ledger.event("restock",2,"none",0,0,0,"Return",now+1,null);es.add(returned);es.add(Ledger.event("undo",0,"none",0,0,0,"Mistaken return",now+2,returned.id()));var r=Finance.calculate(es,Map.of(),Ledger.list(),Ledger.list(),Ledger.list(),Map.of(),Map.of(returned.id(),sale.id()));eq(all(r).cogs(),416L);eq(r.inventoryValue(),3751L);});
        System.out.println("FINANCE RESULTS: "+passed+" passed, 0 failed.");
    }
}
